export function mrOp(base,m,op,o={}){const D={...(m.disp||{})},top=mrTop(m),bake=(B,P)=>{let E=B;for(let k=1;k<=top;k++){const S=catmull(E),F=mrFrames(S),d=new Float32Array(3*S.nv),T=P[k];for(let v=0;v<S.nv;v++){const q=9*v,x=T[3*v]-S.co[3*v],y=T[3*v+1]-S.co[3*v+1],z=T[3*v+2]-S.co[3*v+2];d[3*v]=F[q]*x+F[q+1]*y+F[q+2]*z;d[3*v+1]=F[q+3]*x+F[q+4]*y+F[q+5]*z;d[3*v+2]=F[q+6]*x+F[q+7]*y+F[q+8]*z;}D[k]=d;S.co.set(T.subarray(0,3*S.nv));E=S;}},chain=()=>{const P=[];let E=base;for(let k=1;k<=top;k++){E=multires(E,{disp:{1:D[k]}},1);P[k]=Float64Array.from(E.co.subarray(0,3*E.nv));}return P;};
  if(op==='subdivide'){if(top>=5)throw new Error('Five levels is the limit');const E=catmull(multires(base,m,top));D[top+1]=new Float32Array(3*E.nv);return{disp:D,top:top+1};}
  if(op==='delete_higher'){const L=o.level??m.sculpt??0;for(const k of Object.keys(D))+k>L&&delete D[k];return{disp:D,top:Math.min(top,L)};}
  if(op==='apply_base'){if(!top)throw new Error('Subdivide first');const P=chain(),B=base.clone();for(let it=0;it<4;it++){let S=B;for(let k=0;k<top;k++)S=catmull(S);for(let v=0;v<B.nv;v++)for(let k=0;k<3;k++)B.co[3*v+k]+=P[top][3*v+k]-S.co[3*v+k];}bake(B,P);return{base:B,disp:D,top};}
  if(op==='reshape'){const X=o.target;if(!X)throw new Error('Pick a mesh to copy the shape from');if(X.nv===base.nv){const B=base.clone();B.co.set(X.co.subarray(0,3*B.nv));return{base:B,disp:D,top};}if(!top)throw new Error('The shapes need the same number of points');const P=chain(),S=catmull(multires(base,m,top-1));if(S.nv!==X.nv)throw new Error('The shapes need the same number of points ('+S.nv+' or '+base.nv+')');P[top]=Float64Array.from(X.co.subarray(0,3*X.nv));bake(base,P);return{disp:D,top};}
  throw new Error('Unknown multires operation '+op);}
export function mrData(old,disp,top){const n={},c={};for(let k=1;k<=top;k++){const d=disp[k];if(!d)break;n[k]=d.length/3;c[k]=MS.patchArr(old&&old.c&&old.c[k],d,12,null);}return{n,c};}
